  3	import com.fream.back.domain.order.dto.PayAndShipmentRequestDto;
  4	import com.fream.back.domain.order.exception.InvalidPaymentShipmentDataException;
  5	import com.fream.back.domain.order.exception.OrderAccessDeniedException;
  6	import com.fream.back.domain.order.service.kafka.OrderEventProducer;
  7	import com.fream.back.global.dto.ResponseDto;
  8	import com.fream.back.global.utils.SecurityUtils;
  9	import jakarta.validation.Valid;
 10	import lombok.RequiredArgsConstructor;
 11	import lombok.extern.slf4j.Slf4j;
 12	import org.springframework.http.HttpStatus;
 13	import org.springframework.http.ResponseEntity;
 14	import org.springframework.validation.annotation.Validated;
 15	import org.springframework.web.bind.annotation.*;
 16	
 17	import java.util.HashMap;
 18	import java.util.Map;
