     5	import com.fream.back.domain.sale.service.command.SaleBidCommandService;
     6	import com.fream.back.global.utils.SecurityUtils;
     7	import lombok.RequiredArgsConstructor;
     8	import org.springframework.http.ResponseEntity;
     9	import org.springframework.web.bind.annotation.*;
    10	
    11	@RestController
    12	@RequestMapping("/sale-bids")
    13	@RequiredArgsConstructor
    14	public class SaleBidCommandController {
    15	
    16	    private final SaleBidCommandService saleBidCommandService;
    17	
    18	    // 판매 입찰 생성
    19	    @PostMapping
    20	    public ResponseEntity<Long> createSaleBid(
    21	            @RequestBody SaleBidRequestDto requestDto) {
    22	        String email = SecurityUtils.extractEmailFromSecurityContext(); // 이메일 추출
    23	        Long saleBidId = saleBidCommandService.createSaleBid(
    24	                email,
    25	                requestDto.getProductSizeId(),
    26	                requestDto.getBidPrice(),
