    94	        log.info("사용자 [{}]가 판매 입찰(ID: {})에 대한 즉시 구매를 요청합니다. 창고 보관 여부: {}",
    95	                email, requestDto.getSaleBidId(), requestDto.isWarehouseStorage());
    96	
    97	        // 결제 정보 보강
    98	        PaymentRequestDto paymentRequest = enrichPaymentRequest(requestDto.getPaymentRequest(), email);
    99	
   100	        // 서비스 호출
   101	        Long orderId = orderBidCommandService.createInstantOrderBid(
   102	                email,
   103	                requestDto.getSaleBidId(),
   104	                requestDto.getAddressId(),
   105	                requestDto.isWarehouseStorage(),
   106	                paymentRequest
   107	        ).getId();
   108	
   109	        return ResponseEntity.ok(ResponseDto.success(orderId, "즉시 구매가 성공적으로 처리되었습니다."));
   110	    }
   111	
   112	    /**
   113	     * 결제 요청 정보를 보강합니다.
   114	     *
   115	     * @param paymentRequest 결제 요청 정보
   116	     * @param email 사용자 이메일
   117	     * @return 보강된 결제 요청 정보
   118	     */
   119	    private PaymentRequestDto enrichPaymentRequest(PaymentRequestDto paymentRequest, String email) {
   120	        paymentRequest.setUserEmail(email);
   121	        paymentRequest.setOrderId(null); // 초기에는 null로 설정, 이후 Order 생성 후 업데이트 가능
   122	        return paymentRequest;
   123	    }
   124	}

